CREATE TABLE IF NOT EXISTS `users` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  `email` VARCHAR(320) NOT NULL,
  `name` VARCHAR(80) NOT NULL,
  `role` VARCHAR(255) DEFAULT 'member' NOT NULL CHECK (`role` IN ('member', 'admin'))
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin;

CREATE UNIQUE INDEX `users_email_key` ON `users` (`email`);

CREATE TABLE IF NOT EXISTS `api_keys` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  `user_id` CHAR(36) NOT NULL,
  `hash` VARCHAR(64) NOT NULL,
  `label` VARCHAR(80) DEFAULT 'default' NOT NULL,
  CONSTRAINT `api_keys_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin;

CREATE UNIQUE INDEX `api_keys_hash_key` ON `api_keys` (`hash`);

CREATE TABLE IF NOT EXISTS `notes` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `created_at` DATETIME(3) NOT NULL,
  `updated_at` DATETIME(3) NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `body` MEDIUMTEXT DEFAULT ('') NOT NULL,
  `color` VARCHAR(20),
  `owner_id` CHAR(36) NOT NULL,
  CONSTRAINT `notes_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_bin;
